DROP TABLE IF EXISTS `xwq_ai_disease`;
CREATE TABLE `xwq_ai_disease`  (
  `disease_id` bigint(0) NOT NULL AUTO_INCREMENT COMMENT '唯一标识一条病虫害识别结果',
  `record_id` bigint(0) NOT NULL COMMENT '关联识别记录表 record_id',
  `image_id` bigint(0) NOT NULL COMMENT '关联图片信息表 image_id',
  `disease_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '病虫害名称，如条锈病、白粉病、叶枯病等',
  `disease_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '病虫害标准编码',
  `disease_crop` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '作物类型，如小麦、玉米、水稻',
  `disease_confidence` decimal(6, 5) DEFAULT NULL COMMENT '模型预测置信度',
  `disease_result` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '模型给出的诊断结论',
  `disease_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '识别到的症状表现',
  `disease_advice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '药剂防治、农艺措施等建议',
  `disease_result_img_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '识别后的标注图、打框图',
  `is_warning` tinyint(0) NOT NULL DEFAULT 0 COMMENT '是否触发预警：0 否，1 是',
  `warning_level` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '生成的预警等级',
  `create_time` datetime(0) DEFAULT CURRENT_TIMESTAMP COMMENT '识别结果创建时间',
  `disease_b` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `disease_c` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段3',
  `disease_d` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段4',
  `disease_e` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段5',
  `disease_f` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段6',
  `disease_g` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段7',
  `disease_h` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段8',
  `disease_i` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段9',
  `disease_j` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备用字段10',
  PRIMARY KEY (`disease_id`) USING BTREE,
  INDEX `idx_disease_record_id`(`record_id`) USING BTREE,
  INDEX `idx_disease_image_id`(`image_id`) USING BTREE,
  INDEX `idx_disease_name`(`disease_name`) USING BTREE,
  INDEX `idx_disease_crop`(`disease_crop`) USING BTREE,
  INDEX `idx_disease_warning`(`is_warning`) USING BTREE,
  INDEX `idx_disease_create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9196 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '病虫害识别结果表' ROW_FORMAT = Dynamic;

