INSERT INTO `xwq_ai_disease` VALUES (9001, 9001, 9001, '条锈病', 'WHEAT_STRIPE_RUST', '小麦', 0.96320, '识别结果为小麦条锈病，置信度较高。', '叶片表面出现黄橙色条状病斑，沿叶脉方向分布，局部区域有锈粉状孢子堆。', '建议及时清除重病叶，合理密植并改善田间通风；必要时可选用三唑类或甲氧基丙烯酸酯类药剂按当地植保要求防治。', '/profile/upload/ai/result/wheat_stripe_rust_001_result.jpg', 1, '中度预警', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9002, 9002, 9002, '麦蚜', 'WHEAT_APHID', '小麦', 0.92850, '识别结果为麦蚜危害，虫口数量偏高。', '图像中可见多个小型蚜虫个体聚集，部分叶片和穗部存在刺吸危害迹象。', '建议结合虫口密度和天敌数量综合判断；达到防治指标时可采用生物防治或低毒高效药剂进行点片防治。', '/profile/upload/ai/result/wheat_aphid_trap_001_result.jpg', 1, '轻度预警', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9003, 9003, 9003, '健康', 'WHEAT_HEALTHY', '小麦', 0.88460, '未检测到明显病虫害症状。', '植株叶片颜色较均匀，未见明显锈粉、霉层、坏死斑或虫体聚集。', '建议保持常规巡田，继续监测温湿度、虫口密度和田间长势变化。', '/profile/upload/ai/result/wheat_heading_stage_001_result.jpg', 0, '无预警', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9004, 9004, 9004, '玉米叶斑病', 'MAIZE_LEAF_SPOT', '玉米', 0.91730, '识别结果为玉米叶斑病，需加强田间巡查。', '叶片出现褐色或灰褐色椭圆形病斑，部分病斑边缘较清晰，存在扩大趋势。', '建议清除病残体，避免大水漫灌；发病初期可结合当地植保方案选择合适杀菌剂。', '/profile/upload/ai/result/maize_leaf_spot_001_result.jpg', 1, '轻度预警', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9005, 9005, 9005, '稻瘟病', 'RICE_BLAST', '水稻', 0.94680, '识别结果为水稻稻瘟病，建议及时处理。', '叶片上可见梭形或近椭圆形病斑，中心灰白，边缘褐色，符合稻瘟病典型视觉特征。', '建议控制氮肥用量，保持合理水层；发病初期根据当地植保建议选用登记药剂防治。', '/profile/upload/ai/result/rice_blast_001_result.jpg', 1, '中度预警', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9018, 10001, 20001, '枣瘿蚊', 'JUJUBE_GALL_MIDGE', '冬枣', 0.96250, '检测到枣瘿蚊危害症状', '嫩叶出现卷曲、皱缩和褐变现象，疑似枣瘿蚊幼虫危害。', '及时摘除受害叶片，并结合虫情监测采取诱捕或针对性药剂防治。', '/profile/disease/result_001.jpg', 1, '高风险', '2026-07-01 17:24:16', 'admin', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9019, 10002, 20002, '枣瘿蚊', 'JUJUBE_GALL_MIDGE', '冬枣', 0.93420, '检测到枣瘿蚊轻度危害', '叶缘轻微卷曲，叶片局部出现异常褐色斑点。', '加强田间巡查，及时清理受害叶片，防止虫害扩散。', '/profile/disease/result_002.jpg', 1, '中风险', '2026-06-30 17:24:16', 'admin', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
