INSERT INTO `xwq_ai_disease` VALUES (9021, 10004, 20004, '枣锈病', 'JUJUBE_RUST', '冬枣', 0.87540, '疑似枣锈病', '叶片存在少量黄色斑点，症状较轻，需要人工进一步复核。', '持续观察病斑变化，适当降低园区湿度并加强通风。', '/profile/disease/result_004.jpg', 1, '中风险', '2026-06-28 17:24:16', 'admin', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
