INSERT INTO `xwq_ai_disease` VALUES (9185, 9183, 9029, '枣瘿蚊', NULL, '小麦', 0.99999, '识别结果为枣瘿蚊危害', '嫩叶或生长点受害后出现卷曲、皱缩、停止伸展等症状，严重时影响新梢生长。', '加强嫩梢期监测，及时摘除并集中处理严重受害叶片；在低龄幼虫期结合当地植保建议开展防治。', 'http://localhost:8080/profile/upload/2026/07/17/field__4b21d9998e__DSC03123_2263b0b7_crop01_gall_midge_20260717091026A002.jpg', 0, '无', '2026-07-17 09:10:26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9186, 9184, 9030, '枣蓟马', NULL, '小麦', 0.99999, '识别结果为枣蓟马危害', '嫩叶或嫩梢受害后可能出现失绿、银白色斑、卷曲或生长受阻等症状。', '加强花期和嫩梢期监测，清除田间杂草及受害组织；达到防治指标时按照当地植保建议选择适宜药剂。', 'http://localhost:8080/profile/upload/2026/07/17/field__203c064b22__DSC05738_3d76ea97_crop01_thrips_20260717091049A003.jpg', 0, '无', '2026-07-17 09:10:50', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9187, 9185, 9031, '枣褐斑病', NULL, '小麦', 0.98866, '识别结果为枣褐斑病', '叶片出现褐色或灰褐色病斑，病斑扩展后可能连片并造成叶片早落。', '及时清理病叶和落叶，改善树冠通风透光；结合田间发生程度选用登记药剂，并注意轮换用药。', 'http://localhost:8080/profile/upload/2026/07/17/DSC04594_20260717091501A004.JPG', 0, '无', '2026-07-17 09:15:01', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
