INSERT INTO `xwq_ai_disease` VALUES (9262, 9266, 9105, '枣蓟马', NULL, '枣树', 0.99992, '识别结果为枣蓟马危害', '嫩叶或嫩梢受害后可能出现失绿、银白色斑、卷曲或生长受阻等症状。', '加强花期和嫩梢期监测，清除田间杂草及受害组织；达到防治指标时按照当地植保建议选择适宜药剂。', 'http://localhost:8080/profile/upload/2026/07/20/field__73ce0991f0__DSC05106_a8f557eb_crop01_thrips_20260720211130A067.jpg', 0, '无', '2026-07-20 21:12:10', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
