INSERT INTO `xwq_ai_disease` VALUES (9290, 9294, 9133, '枣褐斑病', NULL, '枣树', 0.99999, '识别结果为枣褐斑病', '叶片出现褐色或灰褐色病斑，病斑扩展后可能连片并造成叶片早落。', '及时清理病叶和落叶，改善树冠通风透光；结合田间发生程度选用登记药剂，并注意轮换用药。', 'http://localhost:8080/profile/upload/2026/07/20/field__9de818fb36__DSC04758_ba44b6a3_crop01_brown_spot_20260720211132A095.jpg', 0, '无', '2026-07-20 21:12:26', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `xwq_ai_disease` VALUES (9291, 9295, 9134, '健康叶片', NULL, '枣树', 0.99986, '未发现明显病虫害，识别结果为健康叶片', '叶片外观正常，未见模型可识别的枣褐斑病、枣瘿蚊或枣蓟马典型特征。', '继续保持日常巡查和合理水肥管理，重点关注嫩梢、叶背及近期新出现的异常斑点。', 'http://localhost:8080/profile/upload/2026/07/20/field__9e993e3bfc__DSC02185_0b708c94_crop01_healthy_20260720211132A096.jpg', 0, '无', '2026-07-20 21:12:27', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
